// seed: tests/seed.free.spec.ts
// Расхождения плана с живым приложением (19.11.2026):
//  - суперлайк от user2 у free уже раскрыт (бесплатное раскрытие): кнопки «לראות מי בעניין שלך» внизу НЕТ — проверяем её отсутствие, не нажимаем;
//  - при открытии /likes по умолчанию выбрана вкладка «בעניין שלך (1)», вкладка «סופר לייק» без счётчика;
//  - плашка «שלחה לך סופר לייק» и имя «QA דתי, 56» — в одной карточке (role=button), город и расстояние: «תל אביב • 8 ק״מ».
// Размытие лица — только визуально, автоматически не проверяется.
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/free-r13.json'),
  colorScheme: 'dark',
});

test.describe('Раунд 13: free видит размытое лицо (#2c21cd)', () => {
  test('סופר לייק: карточка с фото, именем и возрастом, без заглушки @iphone @prod-safe', async ({ page }) => {
    // 1. /likes → вкладка «סופר לייק»
    await page.goto('/likes');
    await page.getByRole('tab', { name: 'סופר לייק' }).click();
    await expect(page.getByRole('tab', { name: 'סופר לייק' })).toHaveAttribute('aria-selected', 'true');

    const card = page.getByRole('button', { name: /^QA .+, \d+/ }).first();
    await expect(card).toBeVisible({ message: 'нет суперлайка у free — подготовить данные (ОКРУЖЕНИЕ)' });

    // имя и возраст, город и расстояние, плашка суперлайка
    await expect(card.getByText(/^QA .+, \d+$/)).toBeVisible();
    await expect(card.getByText(/.+ • \d+ ק״מ/)).toBeVisible();
    await expect(card.getByText(/ש(לחה|לח) לך סופר לייק/)).toBeVisible();

    // фото загружено (naturalWidth > 0), не силуэт-заглушка
    const photo = card.locator('img[alt=""]').first();
    await expect(photo).toBeVisible();
    await expect.poll(() => photo.evaluate((img: HTMLImageElement) => img.naturalWidth)).toBeGreaterThan(0);
    await expect(photo).toHaveAttribute('src', /supabase\.co\/storage\/v1\/object\/public\/avatars\//);

    // нет «לשדרג ל-Premium» вместо имени; кнопка «לראות מי בעניין שלך» не показана (карточка уже раскрыта)
    await expect(card.getByText('לשדרג ל-Premium')).toBeHidden();
    await expect(page.getByText('לראות מי בעניין שלך')).toBeHidden();
    await page.screenshot({ path: 'test-results/superlike-free-card.png' });

    // 2. Вкладка «בעניין שלך» (фильтр «מי עשה לייק») — то же имя, счётчик ≥ 1
    const likesTab = page.getByRole('tab', { name: /^בעניין שלך/ });
    await expect(likesTab).toHaveText(/\(([1-9]\d*)\)/);
    await likesTab.click();
    await expect(page.getByRole('radio', { name: 'מי עשה לייק' })).toBeVisible();
    await expect(page.getByRole('button', { name: /^QA .+, \d+/ }).first()).toBeVisible();
  });
});
